import json,copy,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2];OLD=P.parent/'batch-02';QA=ROOT/'agent-artifacts/qa/batch-02'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
protected=[p for folder in [OLD,QA,ROOT/'agent-artifacts/manifests/v2.2'] for p in folder.rglob('*') if p.is_file()]+[ROOT/'InteractiveBook/TrainerContent/cases.json',ROOT/'InteractiveBook/TrainerContent/topics.json',ROOT/'InteractiveBook/WebContent/index.html',ROOT/'docs/TRAINER-CONTENT-SCHEMA.md']+list((ROOT/'InteractiveBook/Trainer').glob('*.swift'))
ph={str(p.relative_to(ROOT)):sha(p) for p in protected};hfile=P/'protected-input-hashes.json'
if hfile.exists():assert json.loads(hfile.read_text())==ph
else:hfile.write_text(json.dumps(ph,ensure_ascii=False,indent=2)+'\n')
for rel,h in json.loads((QA/'QA-verdict.json').read_text())['inputHashes'].items():assert sha(ROOT/rel)==h
raw=(OLD/'cases_TC051_TC075.json').read_text();bank=json.loads(raw);before=copy.deepcopy(bank);by={c['id']:c for c in bank['cases']}
def option(t,q,e,tempt,w,p):return dict(text=t,decisionQuality=q,isBest=q==1,reasoningPattern=p,failurePattern=None if q==1 else p,explanation=e,whyTempting=tempt,whyNotBest=e,whenItWouldBeBest=w)
def update(id,**kwargs):
 c=by[id];c.update(kwargs);c['revision']=2
 for letter,o in zip('ABCD',c['options']):o['id']=letter
 c['options'][next(i for i,o in enumerate(c['options']) if o['isBest'])]['reasoningPattern']=c['primaryPattern']
# F-DM-T01: shared information structure, cost overlap and uncertain secondary effects.
base=('Портфельный комитет выбирает место новой двухнедельной инициативы Н. Стратегическое соответствие Н, уже начатой Р и следующей К подтверждено; внешних обязательных сроков нет. Одна команда завершит Р через две недели, затем К ещё за две; деление Н не даёт отдельного результата. Р создаёт компонент, но бизнес получает результат только после К. Приоритеты сейчас считают по карточкам: владельцы Р и К записали каждый потери по одним и тем же заказам клиентов. В обоих реестрах указаны совпадающие ID заказов и та же недополученная маржа; иных потерь по ним не заявлено. Если вставить Н между Р и К, общий результат Р–К задержится: потери по этим заказам составят 5–7 млн ₽. При прерывании Р сорвётся интеграционное окно: потери тех же заказов составят 12–14 млн ₽; отдельно остановка и возврат команды стоят точно 6 млн ₽. Диапазоны отражают ещё неизвестный объём клиентских заказов, вероятностей внутри них нет; раньше следующего месяца они не сузятся. Подрядчик предлагает разработать Н за те же две недели за доплату 3 млн ₽. Но приёмку любого результата проводит один внутренний специалист в двухнедельных окнах: ближайшие заняты Р и К, следующее свободное — конец шестой недели. Без приёмки результат не используется. Внутренний пересмотр очереди одновременно меняет владельца соответствующего окна; покупка внешней разработки сама по себе этого не делает. Частичная передача невозможна. Различий по качеству и другим затратам нет. В локальных отчётах Р считается законченной после разработки, а К — самостоятельной новой работой. Комитет может вместо этого закрепить единое обязательство по результату Р–К и согласовать его паузу вместе с зависимыми участниками. Потери Н считаются до принятого результата; общие для всех планов первые две недели не включаются в сравнение. ')
texts=[
'Закончить Р и поставить Н следующей; согласовать перенос общего результата Р–К по одной оценке клиентской потери.',
'Заказать разработку Н внешней команде; сохранить обязательство Р–К и прежние внутренние слоты приёмки.',
'Сохранить ближайшее окно для результата Р–К и закрепить общее обязательство; Н начать после завершения обеих работ.',
'Прервать Р ради Н и пересогласовать зависимые работы; учесть одну клиентскую потерю и отдельную цену возврата команды.'
]
whens=[
'Если ожидание Н до конца Р–К дороже вставки после Р при любом допустимом объёме заказов, а прерывание и внешний исполнитель дороже этой вставки.',
'Если подрядчик обеспечивает также независимую приёмку через две недели, а его полная доплата меньше потерь каждого внутреннего плана.',
'Если ожидание Н до общего результата Р–К дешевле всех способов ускорения на всём допустимом диапазоне клиентской потери.',
'Если ожидание Н и внешняя мощность дороже прерывания даже при верхней границе его последствий, а зависимые обязательства можно пересогласовать.'
]
for n,x,qs in [(51,1,[.7,.7,1,.4]),(52,4,[1,.65,.8,.7]),(53,10,[.7,.35,.4,1])]:
 costs=[(2*x+5,2*x+7),(4*x+3,4*x+3),(4*x,4*x),(18,20)]
 win='CAD'[n-51]
 explanations=[
 f'Разработка Р не равна бизнес-результату: Н отодвигает К и тем самым весь Р–К. Дважды складывать одну клиентскую потерю нельзя. Две недели ожидания Н плюс 5–7 дают {costs[0][0]}–{costs[0][1]} млн ₽.',
 f'Подрядчик закончит код через две недели, но свободная приёмка будет лишь на шестой. Относительно немедленного внутреннего Н это четыре недели потерь плюс 3 млн ₽: всего {4*x+3}. Покупка разработки не покупает пропускную способность приёмки.',
 f'Сохранение обеих стадий удерживает готовность бизнес-результата, а не локальный процент выполнения Р. Четыре недели ожидания Н стоят {4*x} млн ₽.',
 'После паузы нужно изменить обязательства зависимых участников. 12–14 млн ₽ — одна потеря общих заказов; плюс известные 6 за возврат команды дают 18–20, а не две клиентские потери.'
 ]
 minrange=costs['ABCD'.index(win)]
 for i in range(4):
  if 'ABCD'[i]==win:explanations[i]+=' Этот выбор остаётся лучшим на всём диапазоне заказов: точная вероятность не нужна для смены порядка.'
  else:explanations[i]+=f' Он уступает варианту {win} даже при наиболее благоприятной для него границе оценок.'
 if n==53:
  explanations[0]+=' Теперь A оценивается в 25–27, тогда как B — в 43; преимущество A опирается на явное различие дат приёмки, а не придумано в объяснении.'
  explanations[1]+=' Поэтому прежнее равенство A/B больше не существует: B не учитывает общий bottleneck и даёт 43 против 25–27. Более низкое качество B отражает эту ошибку, а не просто его статус distractor.'
 opts=[option(t,q,e,z,w,p) for t,q,e,z,w,p in zip(texts,qs,explanations,['Сохранить начатую Р и дать Н ближайший следующий слот выглядит сбалансированно.','Новая мощность позволяет сохранить обещания обеих инициатив.','Совместное обязательство защищает именно готовый клиентский результат.','Ранняя Н прекращает её потери ожидания, но требует управляемого возврата к Р.'],whens,['queue-with-shared-outcome','buy-independent-capacity','protect-dependent-outcome','controlled-preemption'])]
 update(f'TC-{n:03}',title='Приоритеты связанных результатов',context=base+f'Стоимость задержки принятого Н — {x} млн ₽ в неделю.',question='Какой порядок и единицу портфельного обязательства следует согласовать при этих данных?',options=opts,decisiveFacts=[f'Ожидание Н стоит {x} млн ₽ в неделю при фиксированном двухнедельном размере.','Р и К создают один результат; их локальные оценки описывают одну и ту же потерю заказов.','Внешняя разработка не освобождает общую приёмку; прямое переключение стоит 6 млн ₽, клиентская потеря остаётся в заданном диапазоне.'],keyInsight='Единицей сравнения должен быть достигаемый результат с его зависимостями, а не сумма ценностей карточек.',mentalModel='Восстановите связь работ с общим результатом, исключите повторный счёт одного эффекта и проверьте, меняет ли неопределённость выбор; затем переносите вместе работу и зависимые обязательства.',sourceTopicExplanation='§9.3 рассматривает рейтинг как основу для суждения: Senior учитывает зависимости и ограничения метода, а не исполняет формулу. §9.4 требует согласовать ожидания зависимых участников; это применяется к одному результату Р–К.',authorRationale='Senior: надо сменить объект портфельного решения с карточек на зависимый бизнес-результат, распознать коррелированные оценки потери и отделить их от прямой цены переключения. Также нужно обнаружить, что покупка разработки не покупает пропускную способность приёмки: локально дешёвый внешний старт не ускоряет результат. Затем проверить устойчивость порядка к неизвестному объёму заказов без выдуманной средней вероятности. Общая сложность одинакова у siblings; меняется только CoD Н.')
update('TC-068',title='Зелёный путь и ресурсный сигнал',context='Вы — TPM сервиса заказов. Сработал CPU 90%; текущие latency, error rate и saturation других ресурсов нормальны, autoscaling имеет запас. Проверка реальных заказов сейчас также не выявила ущерба. В истории семь таких вызовов не требовали действий. Но новый разбор показал: дашборд успешности считает долю среди запросов, дошедших до обработчика; при остановке приёма перед ним число запросов исчезает, а последняя зелёная доля сохраняется. Одна такая остановка была при CPU 35%. Ночью легитимный поток меняется от нуля до десяти заказов за окно; дневной порог количества даёт ложные вызовы, а ожидание минимальной выборки может скрыть длительную остановку. Доступны раздельные счётчики входа и завершения, история по времени суток и безопасная синтетическая попытка, проходящая весь путь. Её маршрутизацию на дежурного можно проверить отключением тестового приёма. Нужно решить статус текущего CPU-сигнала и способ защиты пути после удаления шумного вызова.',question='Как изменить реакцию на сигнал, не обменяв шум на незаметную остановку пути?',options=[
option('Считать CPU инцидентом до завершения обновления мониторинга; сохранить вызов по 90% и существующую долю успешных запросов.',.5,'Это сохраняет видимую страховку, но прошлый отказ при CPU 35% ею не покрывается. Текущий ущерб не подтверждён, а семь шумных вызовов продолжаются.','Сохранять старую защиту до появления новой обычно осторожно.','Если CPU-порог доказанно ловит нужный отказ до ущерба и каждое срабатывание требует действия.','retain-proxy-as-safety'),
option('Понизить CPU до предупреждения и вызывать по успешности; при малой выборке накапливать события до надёжной оценки доли.',.6,'Классификация CPU разумна, но накопление выборки не закончится при исчезновении входа; зелёная доля не доказывает доступность пути.','Минимальная выборка защищает от ложного вывода по одному сбою ночью.','Если потеря входа контролируется отдельным рабочим сигналом, а решение по доле можно безопасно отложить до набора событий.','sample-gate-blind-spot'),
option('Понизить CPU до предупреждения и вызывать по объёму входа; применить один минимальный порог независимо от времени суток.',.7,'Контроль входа закрывает слепоту знаменателя, но один порог будет будить на нормальном ночном нуле. Устойчивое правило должно различать режимы трафика.','Количество входов видит исчезновение запросов, которое не отражается в проценте успеха.','Если минимальный нормальный поток стабилен во всех окнах и выбранный порог надёжно отделяет отказ от нормы.','fixed-volume-alert'),
option('Оставить CPU предупреждением; связать вызов с режимом потока и сквозной пробой, испытав обнаружение отказа.',1,'Нужно одновременно видеть вход и завершение: при достаточном потоке — успешность и отклонение объёма, при редком — сквозную пробу. Проверка отключением подтверждает, что путь обнаружения и уведомления работает; просто сменить severity CPU недостаточно.','Можно убрать шум и проверить защиту от отказа без пользовательских событий.','Если доля скрывает исчезновение входа, нормальный трафик неоднороден, а сквозная проба и проверка уведомления доступны.','traffic-aware-end-to-end-alert')],decisiveFacts=['CPU 90% сейчас не сопровождается ущербом, запас autoscaling есть.','Успешность исключает запросы до обработчика; отсутствие событий сохраняет зелёный статус.','Ночной ноль может быть нормой; сквозная проба и испытание отказа доступны.'],keyInsight='Зелёная доля может означать отсутствие наблюдений, а не отсутствие отказа.',mentalModel='Проверьте, какие события попадают в знаменатель и что происходит при их исчезновении; согласуйте чувствительность сигнала с режимом потока и испытайте полный путь обнаружения.',sourceTopicExplanation='§10.4 описывает ситуацию «сервис жив, функция мертва», контроль объёма бизнес-операций, разные пороги для разных режимов трафика, синтетический мониторинг и проверку алертов учениями.',authorRationale='Senior: требуется распознать дефект наблюдаемости в отборе событий, одновременно удержать риск пропуска полного отказа и шум малой выборки, спроектировать сочетание сигналов для разных режимов трафика и проверить путь обнаружения. Понижение severity CPU само по себе оставляет скрытый отказ; это не готовое operational rule.')
update('TC-074',title='Платформенная готовность и общий запуск',context='Вы координируете две программы А и Б. Обе требуют P0 у общей платформы; каждая работа занимает весь ближайший месяц, половина не даёт результата. Portfolio owner доступен сегодня и просит единый исполнимый план. У А большая месячная цена задержки — 5 млн ₽, у Б — 2 млн ₽, оценки уже сопоставимы. Однако старт А требует и платформу, и независимый шлюз: шлюз подтверждён только к концу второго месяца, ускорить его нельзя. Платформа для А, готовая в конце первого или второго месяца, одинаково позволяет старт А в конце второго. Б больше ничего не ждёт и запускается сразу после своей платформенной работы. План Б→А даёт платформу А к подтверждённой дате шлюза; переключение между работами бесплатно. Локальный спонсор А требует первый слот, ссылаясь на свои 5 млн ₽; спонсор Б готовит отдельную эскалацию.',question='Какой общий trade-off предложить portfolio owner вместо двух локальных P0?',options=[
option('Предложить А первым слотом по большей цене задержки; зафиксировать для Б потерю месяца и запросить согласие общего владельца.',.6,'5 млн ₽ описывают задержку запуска А, но ранняя платформа его не ускорит: всё равно нужен шлюз. Такой план добавляет месяц потерь Б без выигрыша А.','При одинаковом размере высокая CoD обычно повышает приоритет.','Если шлюз А готов к концу первого месяца и именно платформа ограничивает более дорогой ранний запуск.','rank-project-cod-not-marginal-slot'),
option('Предложить по половине мощности каждой программе; вынести совместный план владельцу, сохранив равное начало обеих работ.',.3,'Частичные результаты не запускают программы: Б теряет доступный ранний эффект, а А не выигрывает по дате шлюза.','Равное начало выглядит компромиссом между двумя P0.','Если половины работ дают независимые полезные результаты уже в первом месяце и совокупная выгода выше очереди.','split-unusable-capacity'),
option('Закрепить у владельца второй слот за А; первый месяц оставить резервом, не принимая нового обязательства перед Б.',.55,'Зависимость А замечена, но резерв не защищает её дополнительным образом: Б укладывается в первый месяц, А — во второй. Резерв теряет ранний запуск Б.','Резерв снижает риск занять мощность перед важной программой.','Если работа Б не помещается до нужной даты А и её нельзя остановить без недопустимой потери.','reserve-unused-dependency-slack'),
option('Предложить Б сейчас и А следующим слотом; согласовать с владельцем обе даты запуска по полной цепочке зависимостей.',1,'Б стартует на месяц раньше, А — в ту же дату готовности шлюза. Общий план избегает 2 млн ₽ потерь Б без дополнительных потерь А; нужно сравнивать влияние слота, а не полную CoD программ.','Одна очередь может улучшить общий результат без ухудшения более дорогой программы.','Если А всё равно ждёт внешнюю зависимость до второго месяца, а Б можно завершить первым без сдвига платформы А.','marginal-slot-value-across-programs')],decisiveFacts=['Шлюз А готов только к концу второго месяца при любом порядке платформенных работ.','Б запускается сразу после своей платформенной работы.','Б→А сохраняет дату А и ускоряет Б; общую очередь утверждает portfolio owner.'],keyInsight='Стоимость задержки программы не равна стоимости более позднего слота каждой её зависимости.',mentalModel='Для общей мощности сравнивайте изменение дат конечных результатов по полной цепочке: локальный P0 может требовать ресурс раньше, чем он способен дать пользу.',sourceTopicExplanation='§9.4 требует карту «кто от кого что ждёт и когда», согласование даты нужности и готовности и единого решения по общей зависимости. §2.4 объясняет резерв и критический путь: ранняя готовность некритической ветви не ускоряет общий финиш.',authorRationale='Middle: определить предельную ценность слота по двум полным цепочкам и сформировать конкретный общий план. В отличие от TC-012, полномочие portfolio owner не спорно и есть в каждом варианте; одно только направление вопроса к нему не определяет, какая очередь сохраняет обе даты.')
# TC-075 is deliberately unchanged: its frozen diagnostic boundary is the production TC-024 boundary.
# Preserve exact serialized fragments of every unchanged case instead of reserializing the bank.
newraw=raw
for old,new in zip(before['cases'],bank['cases']):
 if old==new:continue
 a=json.dumps(old,ensure_ascii=False,indent=2);b=json.dumps(new,ensure_ascii=False,indent=2)
 # Case objects start at four spaces in the original pretty-printed root.
 a='\n'.join('    '+line for line in a.splitlines());b='\n'.join('    '+line for line in b.splitlines())
 assert newraw.count(a)==1,old['id'];newraw=newraw.replace(a,b,1)
